// unmarshalIntegral_Theta_fits reports whether the Go integer type kind holds the
// integer s.
func unmarshalIntegral_Theta_fits(s, kind string) bool {
	size := strconv.IntSize
	switch strings.TrimPrefix(kind, "u") {
	case "int8":
		size = 8
	case "int16":
		size = 16
	case "int32":
		size = 32
	case "int64":
		size = 64
	}
	if strings.HasPrefix(kind, "u") {
		_, err := strconv.ParseUint(s, 10, size)
		return err == nil
	}
	_, err := strconv.ParseInt(s, 10, size)
	return err == nil
}

